def warehouse_stats(inventory):
    max_val = inventory[0]  # initialise to first element, not 0
    min_val = inventory[0]  # handles all-negative arrays correctly

    for i in range(1, len(inventory)):
        if inventory[i] > max_val:
            max_val = inventory[i]
        if inventory[i] < min_val:
            min_val = inventory[i]

    return [max_val, min_val, max_val - min_val]

