def count_routes_brute(fuel, k):
    n = len(fuel)
    count = 0
    for i in range(n):
        total = 0
        for j in range(i, n):
            total += fuel[j]
            if total == k:
                count += 1
    return count

def longest_broadcast_brute(signal, k):
    if k == 0:
        return 0
    n = len(signal)
    best = 0
    for i in range(n):
        seen = set()
        for j in range(i, n):
            seen.add(signal[j])
            if len(seen) <= k:
                best = max(best, j - i + 1)
            else:
                break
    return best
